use std::path::Path;
fn load(root:&Path,name:&str)->Value {serde_json::from_str(&std::fs::read_to_string(root.join(format!("{name}.json"))).unwrap()).unwrap()}
fn save(root:&Path,name:&str,value:&Value) {std::fs::write(root.join(format!("{name}.json")),serde_json::to_string_pretty(value).unwrap()).unwrap()}
async fn count(pool:&sqlx::SqlitePool,table:&str)->i64 {sqlx::query_scalar(&format!("SELECT COUNT(*) FROM {table}")).fetch_one(pool).await.unwrap()}
async fn snapshot(pool:&sqlx::SqlitePool)->Vec<(String,Vec<String>)> {
 use sqlx::Row;
 let names:Vec<String>=sqlx::query_scalar("SELECT name FROM sqlite_master WHERE type='table' AND name NOT IN ('advisory_candidates','mutation_envelopes','sqlite_sequence') ORDER BY name").fetch_all(pool).await.unwrap();
 let mut output=vec![];
 for name in names {
  let columns=sqlx::query(&format!("PRAGMA table_info(\"{name}\")")).fetch_all(pool).await.unwrap();
  let expr=columns.iter().map(|row|format!("quote(\"{}\")",row.get::<String,_>("name"))).collect::<Vec<_>>().join(" || '|' || ");
  let mut rows:Vec<String>=sqlx::query_scalar(&format!("SELECT {expr} FROM \"{name}\"")).fetch_all(pool).await.unwrap();rows.sort();output.push((name,rows));
 } output
}
